cat > "$TMPDIR/i009/scan.py" << 'EOF'
#!/usr/bin/env python3
"""Scan s03 for: header pointer captured from skb (skb_header_pointer or skb->data
cast or *_hdr(skb) accessor) BEFORE a pskb_may_pull/pskb_pull/__pskb_pull_tail/
skb_linearize call in the same function, then dereferenced after the pull without
a refetch (same variable re-captured from skb accessors after the pull)."""
import os, re, sys

ROOT = "net"
PULL_RE = re.compile(r'\b(pskb_may_pull|pskb_pull|pskb_pull_reserve|__pskb_pull_tail|pskb_may_pull_reason|skb_linearize|__skb_linearize)\s*\(')
# capture: TYPE *var = <expr>; where expr references skb accessors/casts
CAP_RE = re.compile(
    r'^\s*(?:const\s+)?(?:struct\s+)?[\w]+\s*\*\s*([A-Za-z_]\w*)\s*=\s*(.*?);\s*$')
SRC_RE = re.compile(r'skb_header_pointer|skb->data|skb_network_header|skb_transport_header|skb_mac_header|_hdr\(skb|skb_tail_pointer|skb->head')
# usage of var after pull: var->field, var[...], *var, var (as arg)
USE_RE_TMPL = r'\b{v}\b'

def funcs(text):
    """Yield (start_line, function_text, end_line) by brace matching at col 0."""
    lines = text.split('\n')
    n = len(lines)
    i = 0
    while i < n:
        line = lines[i]
        m = re.match(r'^[A-Za-z_].*\)\s*(?:\n)?\{', line) or re.match(r'^[A-Za-z_].*$', line)
        # simpler: find '{' at end of a line starting at col0 within a signature
        if re.match(r'^[A-Za-z_].*\)\s*\{', line):
            # find matching closing brace
            depth = 0
            body_start = i
            j = i
            while j < n:
                depth += lines[j].count('{') - lines[j].count('}')
                if depth == 0 and j >= body_start and '{' in ''.join(lines[body_start:j+1]):
                    yield (body_start, '\n'.join(lines[body_start:j+1]), j)
                    i = j + 1
                    break
                j += 1
            else:
                break
        i += 1

def scan_file(path):
    out = []
    try:
        text = open(path, encoding='utf-8', errors='replace').read()
    except Exception:
        return out
    for (fs, ftext, fe) in funcs(text):
        flines = ftext.split('\n')
        # find capture lines and pull lines
        caps = []  # (idx_in_func, var, expr, line_text)
        pulls = []  # (idx_in_func, call_text)
        for k, ln in enumerate(flines):
            if PULL_RE.search(ln):
                pulls.append((k, ln.strip()))
            for m in CAP_RE.finditer(ln):
                var, expr = m.group(1), m.group(2)
                if SRC_RE.search(expr) and var not in ('skb','dev','sk'):
                    caps.append((k, var, expr, ln.strip()))
        if not caps or not pulls:
            continue
        for (pk, ptxt) in pulls:
            for (ck, var, expr, cline) in caps:
                if ck >= pk:
                    continue
                # check for refetch after pull before first use
                refetched = False
                stale_use_line = None
                for k2 in range(pk+1, len(flines)):
                    ln2 = flines[k2]
                    if re.search(USE_RE_TMPL.format(v=re.escape(var)), ln2):
                        # is this a refetch? var = <expr with skb accessor>
                        rm = re.match(r'^\s*(?:const\s+)?(?:struct\s+)?[\w]+\s*\*\s*'+re.escape(var)+r'\s*=\s*(.*?);\s*$', ln2) or \
                             re.match(r'^\s*'+re.escape(var)+r'\s*=\s*(.*?);\s*$', ln2)
                        if rm and SRC_RE.search(rm.group(1)):
                            refetched = True
                            break
                        if re.search(re.escape(var)+r'\s*(->|\[|\.)', ln2) or re.search(r'(->|\*|\[)\s*'+re.escape(var)+r'\b', ln2) or re.search(r'\b'+re.escape(var)+r'\s*\[', ln2):
                            stale_use_line = (k2, ln2.strip())
                            break
                if not refetched and stale_use_line:
                    out.append((path, fs+ck+1, var, cline, fs+pk+1, ptxt, fs+stale_use_line[0]+1, stale_use_line[1]))
    return out

results = []
for dirpath, dirs, files in os.walk(ROOT):
    dirs[:] = [d for d in dirs if d not in ('selftests',)]
    for f in files:
        if f.endswith('.c'):
            results.extend(scan_file(os.path.join(dirpath, f)))

print(f"total candidate chains: {len(results)}")
for r in sorted(results, key=lambda x: x[0]):
    print(f"{r[0]}:{r[1]} var={r[2]}")
    print(f"   CAPTURE: {r[3]}")
    print(f"   PULL({r[4]}): {r[5]}")
    print(f"   STALEUSE({r[6]}): {r[7]}")
    print()
EOF
python3 "$TMPDIR/i009/scan.py" > "$TMPDIR/i009/scan_out.txt" 2>&1; head -5 "$TMPDIR/i009/scan_out.txt"; grep -c "CAPTURE:" "$TMPDIR/i009/scan_out.txt"

