cat > "$TMPDIR/i009/scan2.py" << 'EOF'
#!/usr/bin/env python3
"""Scan for: pointer into skb captured (skb_header_pointer / skb->data cast /
*_hdr(skb) accessor) BEFORE pskb_may_pull/pskb_pull/__pskb_pull_tail/
skb_linearize, then dereferenced after the pull with no refetch of that var."""
import os, re, sys

ROOTS = sys.argv[1:] or ["net"]
PULL_RE = re.compile(r'\b(pskb_may_pull|pskb_may_pull_reason|pskb_pull|pskb_pull_reserve|__pskb_pull_tail|skb_linearize|__skb_linearize)\s*\(')
CAP_RE = re.compile(r'^\s*(?:const\s+)?(?:struct\s+|enum\s+|union\s+)?[A-Za-z_]\w*\s*\**\s*\*?\s*([A-Za-z_]\w*)\s*=\s*(.+?);\s*(?://.*)?$')
SRC_RE = re.compile(r'skb_header_pointer|skb->data|skb->head|skb_network_header|skb_transport_header|skb_mac_header|\b(ip_hdr|ipv6_hdr|eth_hdr|tcp_hdr|udp_hdr|icmp_hdr|pn_hdr|pn_msg|mpls_hdr|gre_hdr|ah_hdr|arp_hdr|dccp_hdr|sctp_hdr|ip_comp_hdr)\s*\(\s*skb|skb_tail_pointer|skb_shinfo')
DEREF_RE = r'{v}\s*(?:->|\[)'
PASVAL_RE = r'(?:\*|\(|,|\s|return|=)\s*{v}\s*(?:\)|,|;|\[|\+|-)'  # var used as value

def func_ranges(lines):
    """Return list of (start, end_exclusive) approximating top-level functions:
    end is the line index of a '}' at col 0."""
    ends = [i for i, l in enumerate(lines) if l.startswith('}')]
    starts = [0] + [e+1 for e in ends]
    return starts, ends

def scan_file(path):
    out = []
    try:
        lines = open(path, encoding='utf-8', errors='replace').read().split('\n')
    except Exception:
        return out
    starts, ends = func_ranges(lines)
    def fun_start(idx):
        s = 0
        for st in starts:
            if st <= idx: s = st
            else: break
        return s
    def fun_end(idx):
        e = len(lines)
        for en in ends:
            if en >= idx: e = en; break
        return e
    for p, ln in enumerate(lines):
        if not PULL_RE.search(ln):
            continue
        fs, fe = fun_start(p), fun_end(p)
        # captures before pull within function
        for c in range(fs, p):
            m = CAP_RE.match(lines[c])
            if not m: continue
            var, expr = m.group(1), m.group(2)
            if var in ('skb', 'sk', 'dev', 'net') or not SRC_RE.search(expr):
                continue
            if re.search(r'skb_clone|skb_copy|skb_dequeue|kmalloc|kmemdup|skb_peek|alloc_skb|netdev_alloc_skb|build_skb|skb_copy_bits', expr):
                continue
            # search after pull for refetch or stale use
            refetched = False
            stale = None
            for u in range(p+1, fe):
                lu = lines[u]
                if re.search(r'\b' + re.escape(var) + r'\s*=', lu) and SRC_RE.search(lu):
                    # check it's an assignment whose RHS references skb source
                    am = re.search(r'\b' + re.escape(var) + r'\s*=\s*([^;]+);', lu)
                    if am and SRC_RE.search(am.group(1)):
                        refetched = True
                        break
                if re.search(DEREF_RE.format(v=re.escape(var)), lu) or re.search(PASVAL_RE.format(v=re.escape(var)), lu):
                    if re.search(r'\b' + re.escape(var) + r'\s*=', lu):
                        continue  # assignment w/o skb source, treat as refetch-ish
                    stale = (u, lu.strip())
                    break
            if not refetched and stale:
                out.append((path, c+1, var, lines[c].strip(), p+1, ln.strip(), stale[0]+1, stale[1]))
    return out

results = []
for root in ROOTS:
    for dirpath, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d not in ('selftests',)]
        for f in files:
            if f.endswith('.c'):
                results.extend(scan_file(os.path.join(dirpath, f)))

print(f"total candidate chains: {len(results)}")
for r in sorted(results, key=lambda x: (x[0], x[1])):
    print(f"### {r[0]}")
    print(f"  CAPTURE L{r[1]} var={r[2]}: {r[3]}")
    print(f"  PULL    L{r[4]}: {r[5]}")
    print(f"  STALE   L{r[6]}: {r[7]}")
    print()
EOF
python3 "$TMPDIR/i009/scan2.py" net > "$TMPDIR/i009/scan2_net.txt" 2>&1; head -3 "$TMPDIR/i009/scan2_net.txt"; grep -c '^###' "$TMPDIR/i009/scan2_net.txt"

